    pages.forEachIndexed { i, page ->
        sb.append(page.toJson())
        if (i < pages.size - 1) sb.append(",")
    }
    sb.append("],")
    sb.append("\"claims\":${allClaims.size}")
    sb.append("}")
    println(sb.toString())
}

